"""Embed the unmodified XLSX for offline/file:// export (read-only source)."""
import base64
import hashlib
import json
from pathlib import Path

root = Path(__file__).resolve().parent.parent
source = root / 'Насос 600В-1,6_100.xlsx'
data = source.read_bytes()
payload = {'name': source.name, 'sha256': hashlib.sha256(data).hexdigest(),
           'base64': base64.b64encode(data).decode('ascii')}
(root / 'excel-template.bundle.js').write_text(
    '// Generated by scripts/build-excel-template.py; do not edit.\n'
    '(function(root){root.FlangeExcelTemplate=' + json.dumps(payload, ensure_ascii=False)
    + ';})(typeof window!=="undefined"?window:globalThis);\n', encoding='utf-8')
print(f'Excel template: {len(data)} bytes, SHA-256 {payload["sha256"]}')
